"use strict";

const fs = require("fs");
const functions = require("../functions/yamldb.js");
let YAML;

/**
 * YAML file adapter for CroxyDB.
 * @module adapters/yamldb
 */

/**
 * @typedef {Object} YamlDBOptions
 * @property {string} dbName YAML file name without extension.
 * @property {string} dbFolder Folder where the YAML file is stored.
 * @property {string} [seperator="."] Nested-key separator.
 */

/**
 * Stores data in a local YAML file.
 * @class
 */
class YamlDB {
  /**
   * Creates a YAML adapter.
   * @param {YamlDBOptions} options Adapter options.
   */
	constructor(options) {
		  this.dbName = options["dbName"];
	    this.dbFolder = options["dbFolder"];
      this.seperator = options["seperator"]
      this.message = require("../language/en.json");
      try {
        YAML = require("yaml");
      } catch (error) {
        throw new TypeError("You must install \"yaml\" module for use this adapter.");
      }

      functions.fetchFiles(this.dbFolder, this.dbName);
	}

  /**
   * Reads and parses the YAML database file.
   * @returns {Object}
   */
  readContent() {
    functions.fetchFiles(this.dbFolder, this.dbName);
    return YAML.parse(fs.readFileSync(`./${this.dbFolder}/${this.dbName}.yaml`, "utf8")) || {};
  }

  /**
   * Writes YAML content to disk.
   * @param {Object} content Database content.
   * @returns {void}
   */
  writeContent(content) {
    fs.writeFileSync(`./${this.dbFolder}/${this.dbName}.yaml`, YAML.stringify(content || {}));
  }

	set(db, data) {
    functions.fetchFiles(this.dbFolder, this.dbName);

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    var content = this.readContent();
    functions.set(db, data, content, this.seperator);
    this.writeContent(content);
    return this.get(db);

    
  }

  get(db) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();

    try {
      return functions.get(content, this.seperator, ...db.split(this.seperator));
    } catch(err) {
      return undefined;
    }

  }

  fetch(db) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();

    try {
      return functions.get(content, this.seperator, ...db.split(this.seperator));
    } catch(err) {
      return undefined;
    }

  }

  has(db) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();

    try {
      return functions.has(content, this.seperator, ...db.split(this.seperator));
    } catch(err) {
      return false;
    }

  }

  delete(db) {
    functions.fetchFiles(this.dbFolder, this.dbName);

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();

    if(!functions.has(content, this.seperator, ...db.split(this.seperator))) {
      return false;
    }

    functions.remove(content, db, this.seperator);
    functions.removeEmptyData(content);
    
    this.writeContent(content);

    return true;
  }

  add(db, number) {
    
    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    this.set(db, Number(this.get(db) ? (isNaN(this.get(db)) ? Number(number) : this.get(db)+Number(number)) : Number(number)));
    
    return this.get(db);

  }

  subtract(db, number) {
    
    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    this.set(db, (this.get(db) || 0) - Number(number));
    return this.get(db);

  }

  push(db, data) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    var arr = [];

    if(this.get(db)) {
      if(typeof this.get(db) !== "object") {
        arr = [];
      } else {
        arr = this.get(db);
      }
    }

    arr.push(data);

    this.set(db, arr);

    return this.get(db);

  }

  unpush(db, data) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    var arr = [];

    if(this.get(db)) {
      arr = this.get(db);
    }

    arr = arr.filter((x) => x !== data);

    this.set(db, arr);

    return this.get(db);

  }

  delByPriority(db, number) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(isNaN(number)) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(!this.get(db) || this.get(db).length < 1) {
      return false;
    }

    let content = this.get(db);
    let neww = [];

    if (typeof content !== "object") {
      return false;
    }

    for (let a = 0; a < content.length; a++) {
      if (a !== (number-1)) {
        neww.push(content[`${a}`]);
      }
    }

    this.set(db, neww);
    return this.get(db);

  }

  setByPriority(db, data, number) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(isNaN(number)) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(!this.get(db) || this.get(db).length < 1) {
      return false;
    }

    let content = this.get(db);
    let neww = [];

    if (typeof content !== "object") {
      return false;
    }

    for (let a = 0; a < content.length; a++) {
      let val = content[`${a}`];

      if(a === (number-1)) {
        neww.push(data);
      } else {
        neww.push(val);
      }
    }

    this.set(db, neww);
    return this.get(db);

  }

  all() {
    var content = this.readContent();

    return content;
  }

  deleteAll() {

    this.writeContent({});

    return true;

  }

}

module.exports = YamlDB;
